// Original paused energy bookkeeping. Notebook is an identity token, never data.
export const energySizes=Object.freeze([8,12,16]);
export const energyFamilies=Object.freeze(['grind','closed','spread','rub','split','leave']);
const templates=[
 ['Grinding for the café','Grind at least {N/2} steps.',"Where did the wheel's energy go?"],
 ['The closed gate','Close the gate, then grind while some water stays high.','How can the wheel still grind with the gate closed?'],
 ['Follow it to warmth',"Let this batch's tracked energy all reach thermal stores.",'Has any tracked energy disappeared?'],
 ['Rubbing without grinding','Make at least {N/4} rubbing steps with no grinding in this picture.','What warmed while no grain was being ground?'],
 ['Two ways to warm','Make at least {N/4} grinding steps and at least {N/4} rubbing steps.','How are these two steps different?'],
 ['Still water, still energy','Grind at least {N/4} steps. Close the gate. Leave the wheel stopped and some water high.','Which store still has energy when the wheel stops?']
];
export const energyCases=Object.freeze(energySizes.flatMap(size=>energyFamilies.map((kind,i)=>Object.freeze({size,kind,title:templates[i][0],request:templates[i][1].replaceAll('{N/2}',size/2).replaceAll('{N/4}',size/4),talk:templates[i][2]}))));
const freshWork=(N,done=false)=>({waiting:N,moving:0,grinding:0,rubbing:0,gate:true,closedGrind:false,done,lastAction:null});
export const freshEnergyBook=()=>({current:0,page:'work',view:'scene',held:null,works:energyCases.map(c=>freshWork(c.size))});
export const energyCase=(s,index=s.current)=>Number.isInteger(index)&&index>=0&&index<18?energyCases[index]:null;
export function energyGoal(w,c){if(!w||!c)return false;switch(c.kind){case'grind':return w.grinding>=c.size/2;case'closed':return w.closedGrind;case'spread':return w.waiting===0&&w.moving===0;case'rub':return w.rubbing>=c.size/4&&w.grinding===0;case'split':return w.grinding>=c.size/4&&w.rubbing>=c.size/4;case'leave':return w.grinding>=c.size/4&&w.moving===0&&w.waiting>=2&&!w.gate;default:return false;}}
export function energyView(s){const item=energyCase(s),work=s.works[s.current],base=Math.floor(s.current/6)*6,thermal=work.grinding+work.rubbing;return {item,work,base,thermal,total:work.waiting+work.moving+thermal,met:energyGoal(work,item),count:s.works.slice(base,base+6).filter(w=>w.done).length,high:work.waiting/2,low:(item.size-work.waiting)/2};}
export function changeEnergyBook(s,action,value){
 if(!s||!energyCase(s))return null;
 if(action==='size'&&!energySizes.includes(value)||action==='job'&&(!Number.isInteger(value)||value<0||value>5)||action==='view'&&!['scene','book'].includes(value))return null;
 const c=energyCase(s),base=Math.floor(s.current/6)*6,n={...s,works:s.works.map(w=>({...w}))},w=n.works[n.current];
 if(action==='pour'){if(!w.gate||w.waiting<2)return null;w.waiting-=2;w.moving+=2;}
 else if(action==='grind'){if(w.moving<1)return null;w.moving--;w.grinding++;if(!w.gate&&w.waiting>=2)w.closedGrind=true;}
 else if(action==='rub'){if(w.moving<1)return null;w.moving--;w.rubbing++;}
 else if(action==='gate')w.gate=!w.gate;
 else if(action==='restart'){n.works[n.current]={...freshWork(c.size,w.done),lastAction:'restart'};return n;}
 else if(action==='size'){n.current=energySizes.indexOf(value)*6+s.current%6;return n;}
 else if(action==='job'){n.current=base+value;n.page='work';return n;}
 else if(action==='jobs'){n.page='jobs';return n;}
 else if(action==='return'){n.page='work';return n;}
 else if(action==='view'){n.view=value;return n;}
 else if(action==='keep'){n.held={size:c.size,kind:c.kind,waiting:w.waiting,moving:w.moving,grinding:w.grinding,rubbing:w.rubbing,gate:w.gate};return n;}
 else if(action==='clear'){n.held=null;return n;}
 else if(action==='next'){const next=Array.from({length:6},(_,i)=>base+(s.current-base+i+1)%6).find(i=>!s.works[i].done);if(next===undefined)n.page='jobs';else{n.current=next;n.page='work';}return n;}
 else if(action==='fresh-six'){if(!s.works.slice(base,base+6).every(x=>x.done))return null;for(let i=base;i<base+6;i++)n.works[i]=freshWork(c.size);n.current=base;n.page='work';return n;}
 else return null;
 w.lastAction=action;w.done=w.done||energyGoal(w,c);return n;
}
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(a,label,extra='')=>`<button type="button" data-energy-action="${a}" ${extra}>${esc(label)}</button>`;
export function energyAngles(v){return {wheel:((v.item.size-v.work.waiting)/2+v.work.grinding+v.work.rubbing)*15,stone:v.work.grinding*30};}
export function energyBookDrawing(v,scope='current'){
 const {work:w,item:c}=v,T=w.grinding+w.rubbing,id=`energy-${scope}`,labels=[['Waiting','gravitational',w.waiting,'#6d9fc0'],['Moving','kinetic',w.moving,'#c6a04a'],['Warmth added','thermal',T,'#bc7564']];
 return `<svg data-energy-book="${scope}" viewBox="0 0 740 350" role="img" aria-labelledby="${id}-title ${id}-desc"><title id="${id}-title">${scope==='held'?'Kept':'Current'} energy book</title><desc id="${id}-desc">${w.waiting} chips waiting in high water and Earth, ${w.moving} in the moving wheel, ${T} of warmth added: ${w.grinding} while grinding, ${w.rubbing} without grinding. Tracked total ${c.size}. Each filled square is one equal energy chip, not a physical particle or joule.</desc><defs><pattern id="${id}-rub" width="6" height="6" patternUnits="userSpaceOnUse"><rect width="6" height="6" fill="#eed9c9"/><path d="M-1 1L5 7M2-2L8 4" stroke="#9f6357" stroke-width="2"/></pattern></defs><rect width="740" height="350" fill="#f4efdd"/>${labels.map(([title,sub,count,color],i)=>{const x=140+i*220;return `<g data-energy-store="${sub}"><text x="${x+9}" y="18" text-anchor="middle">${title}</text><text x="${x+9}" y="35" text-anchor="middle" class="me-chart-sub">${sub}</text>${Array.from({length:count},(_,j)=>`<rect data-energy-chip="${sub}" data-energy-tag="${i===2?(j<w.grinding?'grinding':'rubbing'):'store'}" x="${x}" y="${328-(j+1)*18}" width="18" height="18" fill="${i===2&&j>=w.grinding?`url(#${id}-rub)`:color}" stroke="#36554a"/>`).join('')}<path d="M${x-12} 40V330H${x+34}" fill="none" stroke="#788978"/></g>`;}).join('')}<text x="370" y="346" text-anchor="middle" class="me-chart-sub">One filled square = one energy chip · same scale throughout</text></svg>`;
}
export function energyScene(v){
 const {work:w,item:c,high,low}=v,a=energyAngles(v),desc=`Paused model: ${high} water portions high and ${low} lower down, same ${c.size/2} portions. Gate ${w.gate?'open':'closed'}. ${w.moving} chips in moving wheel; ${w.grinding+w.rubbing} warmth added. Motion arrows show presence, not speed.`,drop=(x,y)=>`<path d="M${x} ${y-7}q-10 13 0 14q10-1 0-14Z" fill="#78a9c5" stroke="#315e70"/>`;
 return `<svg data-energy-scene viewBox="0 0 740 350" role="img" aria-labelledby="energy-scene-title energy-scene-desc"><title id="energy-scene-title">The mill at a paused moment</title><desc id="energy-scene-desc">${esc(desc)}</desc><rect width="740" height="350" fill="#dfeaf0"/><path d="M0 235Q100 190 210 232T450 226T740 235V350H0Z" fill="#c8d7bf"/><path d="M26 35h100m38-12h85m347 14h78" stroke="#fffdf5" stroke-width="9" stroke-linecap="round"/>
 <path d="M45 78H294V91H45ZM73 91V280M218 91V280" fill="#c5a46b" stroke="#756543" stroke-width="3"/>
 ${Array.from({length:high},(_,i)=>`<g data-energy-water-place="high">${drop(65+i*25,65)}</g>`).join('')}<rect data-energy-gate x="271" y="${w.gate?35:57}" width="13" height="35" rx="2" fill="#8c7150" stroke="#294c43"/>
 <path d="M289 91Q330 100 348 106" fill="none" stroke="#4d8fac" stroke-width="3" stroke-dasharray="5 5"/>
 <rect x="160" y="282" width="310" height="45" rx="12" fill="#eaf0df" stroke="#527766" stroke-width="2"/>${Array.from({length:low},(_,i)=>`<g data-energy-water-place="low">${drop(182+i*35,307)}</g>`).join('')}
 <path d="M405 243Q432 269 418 285" fill="none" stroke="#4d8fac" stroke-width="3" stroke-dasharray="5 5"/>
 <path d="M480 108H692V275H480Z" fill="#e8d3a7" stroke="#6c6850" stroke-width="2"/><path d="M461 110L587 46L714 110Z" fill="#8fa99d" stroke="#36554a" stroke-width="2"/><rect x="632" y="128" width="34" height="42" rx="4" fill="#fff5d7" stroke="#6c6850"/>
 <path d="M315 178H455" stroke="#6c6850" stroke-width="8"/><path d="M455 178H528V210" stroke="#6c6850" stroke-width="3" stroke-dasharray="5 5"/><text x="518" y="165" text-anchor="middle">Grinding step</text>
 <g data-energy-wheel data-energy-angle="${a.wheel}" transform="rotate(${a.wheel} 315 178)"><circle cx="315" cy="178" r="91" fill="#eee0bc" stroke="#52685a" stroke-width="7"/><circle cx="315" cy="178" r="75" fill="#f7edcf" stroke="#6c6850" stroke-width="3"/>${Array.from({length:8},(_,i)=>{const angle=i*Math.PI/4,x=315+83*Math.cos(angle),y=178+83*Math.sin(angle);return `<path d="M315 178L${x} ${y}" stroke="#78694a" stroke-width="4"/><rect x="${x-9}" y="${y-6}" width="18" height="12" rx="2" fill="#b7975b" stroke="#6c6850" transform="rotate(${i*45} ${x} ${y})"/>`;}).join('')}<circle cx="315" cy="178" r="12" fill="#405d50"/></g>
 ${w.moving>0?'<path data-energy-motion-arrow d="M215 148Q226 107 258 91m-3-9 9 6-1 13" fill="none" stroke="#b45e36" stroke-width="4"/>':''}
 <ellipse cx="555" cy="232" rx="62" ry="18" fill="#b6bab0" stroke="#52685a" stroke-width="2"/><g transform="translate(555 224) scale(1 .25)"><circle r="59" fill="#d5d6c8" stroke="#52685a" stroke-width="4"/><g data-energy-stone data-energy-angle="${a.stone}" transform="rotate(${a.stone})"><path d="M-48 0H48M-34-34L34 34M-34 34L34-34" stroke="#8b927f" stroke-width="3"/></g></g><path d="M529 177h52l-17 35h-18Z" fill="#d8b86b" stroke="#6c6850" stroke-width="2"/><path d="M612 253q-12-12 0-27h36q12 15 0 27Z" fill="#f5edd5" stroke="#6c6850" stroke-width="2"/>
 ${w.grinding>0?'<path data-energy-warming="grinding" d="M589 208q-7-8 0-16t0-16m15 28q-7-8 0-16" fill="none" stroke="#b67567" stroke-width="2"/>':''}${w.rubbing>0?'<path data-energy-warming="rubbing" d="M433 162q-7-8 0-16t0-16m14 27q-7-8 0-16" fill="none" stroke="#b67567" stroke-width="2"/>':''}
 <rect x="45" y="96" width="160" height="26" rx="7" fill="#edf1df"/><text x="56" y="114">High portions: ${high}</text><text x="170" y="344">Lower portions: ${low}</text><text x="540" y="296">Grinding steps: ${w.grinding}</text><text x="540" y="317">Rubbing steps: ${w.rubbing}</text></svg>`;
}

const aboutCopy=["Energy is a quantity we can account for, not a material made of little chips. The chips stand for equal amounts; no joule value is chosen here. We track one batch's extra energy, not all the energy already in the room or Earth.", "The gravitational store belongs to the high water and Earth. The wheel has a kinetic store while it moves. Grinding and rubbing add to thermal stores in the stones, flour, axle and nearby surroundings. The two warmth tags say when energy was transferred; they are not two new kinds of energy.", "Each tap advances one model step. Arrows show motion in a paused picture; drawn movement does not measure speed, force or time. Opening the gate only allows the next portion to be poured. The picture does not model continuous flow.", "Pouring is idealized. Real mills also spread energy out while water arrives and flows away. During grinding there is rubbing too; the grinding tag counts the whole tracked thermal increment during that step. It does not measure useful output or efficiency. Real grinding has other small effects, such as making new grain surfaces; our simplified book counts these small effects in with the warming.", "Grinding warms flour; it does not supply flour's chemical food energy. That came from sunlight captured by the growing plant. Resetting starts a different tracked batch in the picture; it does not erase earlier thermal energy in the world."], whyCopy=["Closing the gate stops the next pour; it does not remove energy already in the moving wheel. Grinding or rubbing transfers some out of its kinetic store. When that store is empty in the model, the wheel stops.", "A force is a push or pull. The wheel's kinetic energy is not a stored push. As the water falls and pushes the wheel, energy is transferred by mechanical working. Rubbing forces also transfer energy while surfaces move, warming the mill.", "Thermal stores still hold energy after the wheel stops. That spread-out warmth does not set the wheel turning again by itself."], exampleCopy=["High water: 8. Turning wheel: 0. Warmth added: 0. Total: 8.", "Pour one portion. High water: 6. Turning wheel: 2. Warmth added: 0. Total: 8.", "Grind one step. High water: 6. Turning wheel: 1. Warmth added: 1. Total: 8.", "Let it rub. High water: 6. Turning wheel: 0. Warmth added: 2. Total: 8. One chip was transferred while grinding; one without grinding."];
const introCopy="The café needs flour. Help the miller explore where the mill's energy goes.", boundaryCopy="Model paused between taps. Arrows mark motion in this paused picture. Chips count equal amounts of energy; they are not bits of water or food. We count only this batch’s energy.";
function stateLine(v){const w=v.work;if(w.waiting===0&&w.moving===0)return "This batch's tracked energy is in thermal stores. The wheel has stopped. Start a fresh picture to follow another batch.";if(w.waiting===0)return 'No water remains high in this batch, but the wheel still has moving energy.';if(w.moving===0)return 'The wheel has no moving energy in this picture. Pour a portion to transfer some from high water.'+(!w.gate?' Open the gate first.':'');if(!w.gate)return 'The gate keeps the next portion high. Opening it allows another pour; this paused model does not pour by itself.';return 'Choose a grinding step or let the wheel rub without grinding. Both can warm the mill.';}
function lastLine(a){return {pour:"High water's gravitational store got smaller. The wheel's kinetic store got bigger. The tracked total stayed the same. The poured water flows on, lower down.",grind:"The wheel's kinetic store got smaller. Grinding and rubbing warmed the mill. The tracked total stayed the same.",rub:"The wheel's kinetic store got smaller. Rubbing warmed the mill without grinding. The tracked total stayed the same.",gate:'Changing the gate has not moved any energy in this paused picture.',restart:'Fresh high water starts a separate picture. Your kept picture and other requests stay.'}[a]||'';}
function statusLine(v){if(v.met)return 'This picture meets the request. Keep exploring or try another request.';if(v.work.done)return 'This request was met earlier. You can keep exploring the current picture.';if(v.item.kind==='rub'&&v.work.grinding>0)return 'This picture included grinding. Start a separate picture to explore rubbing only.';return '';}
const opened=(details,k)=>details[k]?'open':'';
function explanations(details){return `<details data-energy-details="example" ${opened(details,'example')}><summary>Try one separate example</summary><p>This example starts with 8 chips. Your own picture waits.</p><ol>${exampleCopy.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></details><details data-energy-details="model" ${opened(details,'model')}><summary>About this paused model</summary>${aboutCopy.map(s=>`<p>${esc(s)}</p>`).join('')}</details><details data-energy-details="why" ${opened(details,'why')}><summary>Why can the wheel keep going?</summary>${whyCopy.map(s=>`<p>${esc(s)}</p>`).join('')}</details><details data-energy-details="sources" ${opened(details,'sources')}><summary>Grown-ups: sources and limits</summary><p>Conservation alone does not rule out ideal lossless motion. This limited model does not test perpetual-motion claims.</p><p>Supplied teaching, not a physical experiment, measurement or assessment. A request met on this table does not establish independent explanation or curriculum mastery. No actions, support requests, reading, hearing, exposure or results are added to the notebook.</p><ul><li><a href="https://openstax.org/books/college-physics-2e/pages/7-6-conservation-of-energy" target="_blank" rel="noopener noreferrer">OpenStax: Conservation of energy</a></li><li><a href="https://www.eia.gov/energyexplained/hydropower/" target="_blank" rel="noopener noreferrer">EIA: Hydropower and the water cycle</a></li><li><a href="https://openstax.org/books/biology-2e/pages/8-1-overview-of-photosynthesis" target="_blank" rel="noopener noreferrer">OpenStax: Photosynthesis and food energy</a></li></ul></details>`;}
function keptPanel(s,v,details){if(!s.held)return '';const h=s.held,rows=[['High water and Earth',v.work.waiting,h.waiting],['Turning wheel',v.work.moving,h.moving],['Warmth added',v.thermal,h.grinding+h.rubbing],['Tracked total',v.item.size,h.size],['Gate',v.work.gate?'open':'closed',h.gate?'open':'closed']];return `<aside class="me-kept"><h2>Kept picture</h2>${button('clear','Clear kept picture')}<p>These are two separate pictures. Different totals mean different batches; this comparison does not isolate one change.</p><table><thead><tr><th></th><th>Current</th><th>Kept</th></tr></thead><tbody>${rows.map(([label,a,b])=>`<tr><th>${label}</th><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table><details data-energy-details="held" ${opened(details,'held')}><summary>See the kept energy book</summary>${energyBookDrawing({work:h,item:{size:h.size}},'held')}</details></aside>`;}
let visit=null,motion=null;
export function stopMillEnergyMotion(){motion?.cancel();motion=null;}
export function resetMillEnergy(){stopMillEnergyMotion();visit=null;}
function current(book,owner){if(!visit||visit.book!==book||visit.owner!==owner){stopMillEnergyMotion();visit={book,owner,model:freshEnergyBook(),details:{}};}return visit;}
export function millEnergyPage(book,owner){
 const local=current(book,owner),s=local.model,v=energyView(s),w=v.work,hear=`${v.item.title}. ${v.item.request} ${w.waiting} chips waiting in high water and Earth. ${w.moving} in the moving wheel. ${v.thermal} warmth added. Tracked total ${v.item.size}. Gate ${w.gate?'open':'closed'}. ${stateLine(v)} ${lastLine(w.lastAction)}`;
 const toolbar=`<div class="me-toolbar"><div role="group" aria-label="Tracked batch size">${energySizes.map(N=>button('size',`${N} chips`,`data-energy-value="${N}" aria-pressed="${v.item.size===N}"`)).join('')}</div><div role="group" aria-label="Picture">${['scene','book'].map(k=>button('view',k==='scene'?'Scene':'Energy book',`data-energy-value="${k}" aria-pressed="${s.view===k}"`)).join('')}</div>${button('jobs','Other requests')}</div>`;
 const milestone=v.count===6?`<aside class="me-complete" role="status"><strong>Six model requests met. The miller has more questions to explore!</strong>${button('fresh-six','Start six fresh requests')}<p>Start six fresh requests replaces this batch size's six pictures. Other batch sizes, your kept picture and open explanations stay.</p></aside>`:'';
 const chooser=`<section class="me-jobs"><h2 id="energy-requests-title" tabindex="-1">Six requests · ${v.count} met</h2><p>Each picture tracks a separate ${v.item.size}-chip batch.</p><p>Every request and batch size is open. Waiting pictures stay where you left them.</p>${energyCases.slice(v.base,v.base+6).map((c,i)=>button('job',`${c.title}${s.works[v.base+i].done?' · met earlier':''}`,`data-energy-value="${i}"`)).join('')}${button('return','Back to this picture')}</section>`;
 const body=`<section class="me-work"><h2 id="energy-request-title" tabindex="-1">${v.item.title}</h2><p class="me-request">${v.item.request}</p><figure class="me-figure">${s.view==='scene'?energyScene(v):energyBookDrawing(v)}<figcaption>${esc(boundaryCopy)}<span class="me-water-total">Same ${v.item.size/2} water portions · ${v.high} high · ${v.low} lower</span></figcaption></figure><section class="me-console" aria-label="Move the model one step"><p class="me-state">${stateLine(v)}</p><div class="me-actions">${button('pour','Pour one portion',`${!w.gate||w.waiting<2?'disabled':''} aria-describedby="energy-pour-help"`)}${button('grind','Grind one step',w.moving<1?'disabled':'')}${button('rub','Let it rub',w.moving<1?'disabled':'')}${button('gate',w.gate?'Close the gate':'Open the gate')}</div><p id="energy-pour-help" class="me-small">One portion transfers 2 chips from high water to the wheel.</p><p data-energy-motion-note hidden>Showing the last model step</p>${lastLine(w.lastAction)?`<p class="me-feedback">${lastLine(w.lastAction)}</p>`:''}<p class="me-status" role="status">${statusLine(v)}</p></section><dl class="me-facts"><div><dt>Waiting · gravitational</dt><dd data-energy-count="waiting">${w.waiting}</dd><span>High water and Earth</span></div><div><dt>Moving · kinetic</dt><dd data-energy-count="moving">${w.moving}</dd><span>Turning wheel</span></div><div><dt>Warmth added · thermal</dt><dd data-energy-count="thermal">${v.thermal}</dd><span>While grinding: ${w.grinding} · Without grinding: ${w.rubbing}</span></div><div class="me-total"><dt>Tracked total</dt><dd data-energy-count="total">${v.total}</dd></div><div class="me-gate"><dt>Gate</dt><dd data-energy-gate-status>Gate ${w.gate?'open':'closed'}</dd></div></dl><p class="me-sum">Warmth added: ${w.grinding} + ${w.rubbing} = ${v.thermal}</p><div class="me-tools">${button('next','Next request')}${button('restart','Start this picture again')}${button('keep',s.held?'Replace kept picture':'Keep this picture')}<button type="button" data-speak="${esc(hear)}">Hear this turn</button></div><p class="me-talk">${v.item.talk} <span>You can talk together; nothing is recorded or graded.</span></p></section>`;
 return `<section class="me-room" data-energy-root><header><a href="#workshop">← Back to Storm Workshop</a><p class="eyebrow">Willowbank · a model at the miller's table</p><h1>The Mill's Energy Book</h1><p>${esc(introCopy)}</p></header>${toolbar}${milestone}${s.page==='jobs'?chooser:body}${keptPanel(s,v,local.details)}<p class="me-local">Pictures wait while you use this table. Leaving or reloading starts fresh. Nothing here changes your saved learning notes.</p>${explanations(local.details)}<nav class="me-related" aria-label="Related models"><a href="#workshop/lift">Compare force and work in the Lift Yard</a><a href="#science/play">Explore water and energy</a><a href="#workshop/lantern">Back to the Lantern Circuit Bench</a></nav></section>`;
}
function anglesFrom(root){const wheel=root.querySelector('[data-energy-wheel]'),stone=root.querySelector('[data-energy-stone]');return wheel&&stone?{wheel:+wheel.dataset.energyAngle,stone:+stone.dataset.energyAngle}:null;}
function animateEnergy(root,from,live){
 if(!from||!live()||document.hidden||typeof matchMedia!=='function'||matchMedia('(prefers-reduced-motion: reduce)').matches||typeof requestAnimationFrame!=='function')return;
 const wheel=root.querySelector('[data-energy-wheel]'),stone=root.querySelector('[data-energy-stone]'),to=anglesFrom(root),note=root.querySelector('[data-energy-motion-note]');if(!wheel||!stone||!to)return;
 let frame=0,start=null,ended=false;const draw=p=>{wheel.dataset.energyAngle=p.wheel;wheel.setAttribute('transform',`rotate(${p.wheel} 315 178)`);stone.dataset.energyAngle=p.stone;stone.setAttribute('transform',`rotate(${p.stone})`);};
 const own={cancel(){if(ended)return;ended=true;if(typeof cancelAnimationFrame==='function')cancelAnimationFrame(frame);if(live())draw(to);root.removeAttribute('data-energy-moving');if(note)note.hidden=true;}};motion=own;draw(from);root.setAttribute('data-energy-moving','true');if(note)note.hidden=false;
 const tick=time=>{if(ended||!live()||document.hidden){own.cancel();if(motion===own)motion=null;return;}if(start===null)start=time;const t=Math.min(1,(time-start)/180),e=1-(1-t)**2;draw({wheel:from.wheel+(to.wheel-from.wheel)*e,stone:from.stone+(to.stone-from.stone)*e});if(t<1)frame=requestAnimationFrame(tick);else{ended=true;root.removeAttribute('data-energy-moving');if(note)note.hidden=true;if(motion===own)motion=null;}};frame=requestAnimationFrame(tick);
}
export function bindMillEnergy(book,{explorerId,notebook,isActive,render,stopSpeech,stopSound}){
 const root=document.querySelector('[data-energy-root]');if(!root)return;const local=current(book,explorerId()),live=()=>visit===local&&root.isConnected&&notebook()===book&&explorerId()===local.owner&&isActive();
 for(const d of root.querySelectorAll('[data-energy-details]'))d.addEventListener('toggle',()=>{if(live())local.details[d.dataset.energyDetails]=d.open;});
 for(const b of root.querySelectorAll('[data-energy-action]'))b.addEventListener('click',()=>{
  if(!live()||b.disabled)return;const action=b.dataset.energyAction,value=['job','size'].includes(action)?Number(b.dataset.energyValue):b.dataset.energyValue,next=changeEnergyBook(local.model,action,value);if(!next)return;
  const from=['pour','grind','rub'].includes(action)&&local.model.view==='scene'?anglesFrom(root):null;stopSpeech();stopSound();stopMillEnergyMotion();for(const d of root.querySelectorAll('[data-energy-details]'))local.details[d.dataset.energyDetails]=d.open;local.model=next;render();
  const now=document.querySelector('[data-energy-root]'),newLive=()=>visit===local&&now?.isConnected&&notebook()===book&&explorerId()===local.owner&&isActive();if(!newLive())return;if(from)animateEnergy(now,from,newLive);
  let target=now.querySelector(`[data-energy-action="${action}"]${['job','size','view'].includes(action)?`[data-energy-value="${value}"]`:''}`);
  if(['job','size','fresh-six','next'].includes(action))target=now.querySelector(next.page==='jobs'?`[data-energy-action="job"][data-energy-value="${next.current%6}"]`:'#energy-request-title');
  if(action==='jobs')target=now.querySelector(`[data-energy-action="job"][data-energy-value="${next.current%6}"]`);
  if(action==='return')target=now.querySelector('[data-energy-action="jobs"]');
  if(action==='restart')target=now.querySelector('[data-energy-action="pour"]');
  if(action==='clear')target=now.querySelector('[data-energy-action="keep"],#energy-requests-title');
  if(target?.disabled){const w=next.works[next.current],fallback=w.moving>0?'grind':w.waiting>0?(w.gate?'pour':'gate'):'next';target=now.querySelector(`[data-energy-action="${fallback}"]`);}
  (target||now.querySelector('#energy-request-title,#energy-requests-title'))?.focus({preventScroll:true});
 });
}
